package com.saucedemo.support;
import com.saucedemo.config.TestConfig; import com.zaxxer.hikari.*; import java.sql.*; import java.util.*;
/** Config-driven JDBC utility. Inject credentials from a secret store in CI. */
public final class DatabaseClient implements AutoCloseable {private final HikariDataSource dataSource;public DatabaseClient(){if(TestConfig.dbUrl().isBlank())throw new IllegalStateException("DB_URL/dbUrl is required for database validation.");HikariConfig config=new HikariConfig();config.setJdbcUrl(TestConfig.dbUrl());config.setUsername(TestConfig.dbUser());config.setPassword(TestConfig.dbPassword());config.setMaximumPoolSize(2);config.setPoolName("ui-test-db-pool");dataSource=new HikariDataSource(config);}public List<Map<String,Object>> query(String sql,List<Object> parameters){try(var connection=dataSource.getConnection();PreparedStatement statement=connection.prepareStatement(sql)){for(int i=0;i<parameters.size();i++)statement.setObject(i+1,parameters.get(i));try(ResultSet results=statement.executeQuery()){List<Map<String,Object>> rows=new ArrayList<>();var metadata=results.getMetaData();while(results.next()){var row=new LinkedHashMap<String,Object>();for(int i=1;i<=metadata.getColumnCount();i++)row.put(metadata.getColumnLabel(i),results.getObject(i));rows.add(row);}return rows;}}catch(SQLException exception){throw new IllegalStateException("Database query failed",exception);}}@Override public void close(){dataSource.close();}}
